'use client'

import * as React from 'react'

// The component brings its own styles. Without this a `gamestage-ui add` installs a
// working but completely unstyled LevelRing, and `tsc --noEmit` passes on it,
// so the gate cannot catch it.
import './level-ring.css'
import { TickGlyph } from './glyphs'

/**
 * LevelRing: the same progress, drawn round.
 *
 * BDS-022 makes this a component rather than a variant of `progress-bar`,
 * because a ring and a bar share no layout code: one is a width, the other is
 * an angle. What they do share is the meaning, and that is expressed
 * identically in both: `data-gs-value` over `data-gs-max`, the same four
 * states, and the same `--gs-progress` custom property carrying the fraction
 * the geometry needs.
 *
 * Specimen 3c draws it as two discs: a 104px ring in the dark with the reached
 * fraction swept round it in the reward colour, and a 76px disc of surface on
 * top carrying the level number and the word LEVEL. design/twins/3c.json
 * measures ours against it. The sweep is a conic gradient on the fill rather
 * than an SVG stroke, because that is what the drawing is and the two look
 * nothing alike at the edges: a stroke has round caps and a fixed width, a
 * sweep fills the whole ring to a hard edge.
 *
 * There is no `data-gs-progress` and no `data-gs-fill` here either. A custom
 * property is not an attribute: nothing selects on it and no test reads it as
 * state.
 *
 * It performs nothing. The host owns the number and says when it is finished.
 */

export interface LevelRingProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, 'children'> {
  /** How far round. Absent only when `indeterminate`. Zero is a real state. */
  value?: number
  /** The ceiling the value counts toward. */
  max?: number
  /** The floor the value counts from. Omitted from the DOM when it is zero. */
  min?: number
  /** Working, with no known fraction. The value is ignored and not announced. */
  indeterminate?: boolean
  /** Finished. The host decides; the component never infers it from the number. */
  complete?: boolean
  /** The word a player reads as this ring's name. */
  label?: string
  /** Render the value as something other than the bare number, e.g. `40%`. */
  format?: (value: number) => string
  /**
   * What sits in the middle: a level number, an icon, a `Stat`. Never announced,
   * because the ring's own accessible name already carries the number.
   */
  children?: React.ReactNode
  /**
   * The word under what sits in the middle, the drawing's LEVEL. Never
   * announced, for the same reason as `children`.
   */
  caption?: string
}

/** Fixed by the attribute contract, so no two progress surfaces disagree. */
const STATE_WORD = {
  indeterminate: 'in progress',
  complete: 'complete',
} as const

/** The tick, because a state that is only a colour is not a state. */
const COMPLETE_GLYPH = <TickGlyph />

export function LevelRing({
  value,
  max = 100,
  min = 0,
  indeterminate = false,
  complete = false,
  label = 'progress',
  format,
  className,
  style,
  children,
  caption,
  ...rest
}: LevelRingProps) {
  const determinate = !indeterminate && value !== undefined
  const span = max - min
  const fraction = determinate
    ? Math.min(1, Math.max(0, span > 0 ? (value - min) / span : 0))
    : 0
  const rendered = determinate ? (format ? format(value) : `${value}`) : undefined

  const words = [label]
  if (determinate) words.push(`${rendered} of ${max}`)
  else words.push(STATE_WORD.indeterminate)
  if (complete) words.push(STATE_WORD.complete)

  return (
    <div
      {...rest}
      className={['gs-level-ring', className].filter(Boolean).join(' ')}
      style={{ ...style, '--gs-progress': fraction } as React.CSSProperties}
      data-gs-component="level-ring"
      data-gs-value={determinate ? value : undefined}
      data-gs-max={determinate ? max : undefined}
      data-gs-min={determinate && min !== 0 ? min : undefined}
      data-gs-indeterminate={indeterminate ? 'true' : undefined}
      data-gs-complete={complete ? 'true' : undefined}
      role="progressbar"
      // No aria-valuenow at all when indeterminate.
      aria-valuenow={determinate ? value : undefined}
      aria-valuemin={min}
      aria-valuemax={max}
      aria-label={words.join(', ')}
    >
      {/* The drawing is hidden from a screen reader, which gets the name on
          the root instead. The track is the dark ring; the fill is the sweep
          over it; the centre is the disc on top. */}
      <div className="gs-level-ring__track" data-gs-scope="level-ring" data-gs-part="track" aria-hidden="true">
        {/* The sweep travels, so it is motion and stops dead under reduced
            motion. Completion therefore also changes the sweep's colour and
            adds a glyph, both emphasis, so a reduced-motion player sees it
            land. */}
        <div
          className="gs-level-ring__fill"
          data-gs-scope="level-ring" data-gs-part="fill"
          data-gs-animates="motion"
        />

        <div className="gs-level-ring__center" data-gs-scope="level-ring" data-gs-part="center">
          {children !== undefined && children !== null ? (
            <span className="gs-level-ring__value" data-gs-scope="level-ring" data-gs-part="value">
              {children}
            </span>
          ) : null}
          {caption ? (
            <span className="gs-level-ring__caption" data-gs-scope="level-ring" data-gs-part="label">
              {caption}
            </span>
          ) : null}
          {complete ? (
            <span
              className="gs-level-ring__glyph"
              data-gs-scope="level-ring" data-gs-part="glyph"
              data-gs-animates="emphasis"
            >
              {COMPLETE_GLYPH}
            </span>
          ) : null}
        </div>
      </div>
    </div>
  )
}

/* Level ring. Every value comes from a token; nothing here is a literal
   colour, size, duration or typeface.

   Specimen 3c draws it and design/twins/3c.json measures ours against it: a
   104px ring in colour.edge, the dark, with the reached fraction swept round
   it in the reward colour, and a 76px disc of surface on top, both ringed at
   the control stroke, the level number in the display face with LEVEL under it.

   The sizes. No token is 104 or 76, and the drawing draws them once and twice.
   What the drawing does draw, everywhere, is space.inset at 14px, and the two
   discs are that: a 48px core, icon.object, with a 14px ring round it (76) and
   another 14px ring round that (104). So the core is the one token and the two
   rings are the inset, and a theme that changes either moves the whole thing
   in proportion. */

/* Registered so the sweep can transition. An unregistered custom property
   changes in one step; a registered <number> interpolates, and the conic
   gradient below is drawn from it. Inherits, because the root sets it and the
   fill reads it, the same arrangement progress-bar uses for its width. */
@property --gs-progress {
  syntax: '<number>';
  inherits: true;
  initial-value: 0;
}

.gs-level-ring {
  display: inline-grid;
  place-items: center;

  /* The fraction of the way round, set by the component. */
  --gs-progress: 0;
  /* BDS-022: the ring fills over motion.fill on the drawing's curve, the same
     tokens as the bar. */
  transition: --gs-progress var(--gs-motion-fill) var(--gs-motion-ease-fill);
}

.gs-level-ring__track {
  --gs-level-ring-core: var(--gs-size-icon-object);

  position: relative;
  box-sizing: border-box;
  width: calc(var(--gs-level-ring-core) + 4 * var(--gs-space-inset));
  height: calc(var(--gs-level-ring-core) + 4 * var(--gs-space-inset));
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--gs-radius-full);
  border: var(--gs-stroke-ui, var(--gs-stroke-hairline)) solid var(--gs-color-edge);
  background: var(--gs-color-edge);
}

/* The sweep. The drawing writes conic-gradient(var(--reward) ...), and in
   arcade --reward is a gradient, which a conic stop cannot hold, so the
   canvas draws no arc at all; the intent is plain and reward-solid is the
   colour it meant. Transparent past the fraction, so the track's dark shows. */
.gs-level-ring__fill {
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: conic-gradient(
    var(--gs-color-reward-solid) 0 calc(var(--gs-progress) * 100%),
    transparent calc(var(--gs-progress) * 100%) 100%
  );
}

/* -- indeterminate -------------------------------------------------------- */
/* A quarter of the ring, spinning. The spin is motion and stops under reduced
   motion, so the arc is also given a length and a colour of its own: a player
   who sees no movement still sees a ring that is plainly not at a position. */
.gs-level-ring[data-gs-indeterminate='true'] .gs-level-ring__fill {
  background: conic-gradient(var(--gs-color-muted) 0 25%, transparent 25% 100%);
  /* The drawing's `gs-rays` keyframe (packages/tokens/motion.css) is one full
     turn, which is exactly what a spinner is, so it is the same keyframe under
     the design's name rather than a copy under this component's. The duration
     is not the rays token, which is an 8s decorative turn behind a reveal; a
     spinner that took eight seconds a lap would read as stuck. */
  animation: gs-rays var(--gs-motion-reveal) var(--gs-motion-ease-rays) infinite;
}

/* -- complete ------------------------------------------------------------- */
/* Three things change at once: the sweep, the glyph, and the centre's ink.
   Two of them are emphasis and survive reduced motion. */
.gs-level-ring[data-gs-complete='true'] .gs-level-ring__fill {
  background: conic-gradient(
    var(--gs-color-positive-solid) 0 calc(var(--gs-progress) * 100%),
    transparent calc(var(--gs-progress) * 100%) 100%
  );
}

.gs-level-ring[data-gs-complete='true'] .gs-level-ring__center {
  color: var(--gs-color-positive-solid);
}

/* The disc on top. Positioned so it paints over the fill, which is positioned
   too; source order alone would not put it there. */
.gs-level-ring__center {
  position: relative;
  box-sizing: border-box;
  width: calc(var(--gs-level-ring-core) + 2 * var(--gs-space-inset));
  height: calc(var(--gs-level-ring-core) + 2 * var(--gs-space-inset));
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  border-radius: var(--gs-radius-full);
  border: var(--gs-stroke-ui, var(--gs-stroke-hairline)) solid var(--gs-color-edge);
  background: var(--gs-color-surface);
  color: var(--gs-color-ink);
}

/* The level number: the stat face, no display shadow. The drawing draws it at
   24px with no shadow; type.stat is 22 and the twins file carries the 2px. */
.gs-level-ring__value {
  font-family: var(--gs-type-stat-font-family);
  font-size: var(--gs-type-stat-font-size);
  font-weight: var(--gs-type-stat-font-weight);
  font-variant-numeric: var(--gs-type-score-font-variant-numeric);
  line-height: 1;
  text-shadow: none;
}

/* The word under it. The drawing sets it at 9px, under the 12px floor; the
   label token is the floor. Its letter-spacing lands on the same 0.72px. */
.gs-level-ring__caption {
  margin-top: var(--gs-space-1);
  font-family: var(--gs-type-label-font-family);
  font-size: var(--gs-type-label-font-size);
  font-weight: var(--gs-type-label-font-weight);
  letter-spacing: var(--gs-type-label-letter-spacing);
  line-height: 1;
  text-transform: uppercase;
  color: var(--gs-color-ink-secondary);
}

.gs-level-ring__glyph {
  display: flex;
  font-size: var(--gs-size-icon-utility);
  line-height: 1;
  /* Emphasis, not motion: this duration survives reduced motion on purpose. */
  transition: opacity var(--gs-motion-emphasis) ease-out;
}
